import numpy as np
import pandas as pd
train = pd.read_csv('train.csv')

def rmse(a,b):
    a=np.array(a,float); b=np.array(b,float)
    return float(np.sqrt(np.mean((a-b)**2)))

methods = {}
truth = []
for ent, g in train.groupby('entity_id', sort=True):
    y = g['target'].to_numpy(float)
    for i in range(len(y)):
        hist = np.delete(y, i)
        truth.append(y[i])
        vals = {
            'mean': hist.mean(),
            'median': float(np.median(hist)),
            'midhinge': float((np.min(hist) + np.max(hist)) / 2.0),
            'trimmed_if4': float(np.mean(np.sort(hist)[0:3])),
            'winsor_mean': float(np.mean(np.clip(hist, np.quantile(hist,0.25), np.quantile(hist,0.75)))),
        }
        for k,v in vals.items():
            methods.setdefault(k, []).append(v)
for k,v in methods.items():
    print(k, rmse(truth,v))
